// Stripe sends amounts in the smallest unit (cents). Zero-decimal currencies such as JPY are already whole.
const ZERO_DECIMAL = ['bif','clp','djf','gnf','jpy','kmf','krw','mga','pyg','rwf','ugx','vnd','vuv','xaf','xof','xpf'];
return $input.all().map((item) => {
  const charge = item.json.data?.object || {};
  const currency = (charge.currency || 'usd').toLowerCase();
  const amount = ZERO_DECIMAL.includes(currency) ? charge.amount : charge.amount / 100;
  const fullName = (charge.billing_details?.name || '').trim();
  const [firstName, ...rest] = fullName.split(' ');
  return {
    json: {
      chargeId: charge.id,
      email: (charge.billing_details?.email || charge.receipt_email || '').toLowerCase(),
      fullName,
      firstName: firstName || '',
      lastName: rest.join(' '),
      amount,
      currency: currency.toUpperCase(),
      amountText: new Intl.NumberFormat('en-US', { style: 'currency', currency: currency.toUpperCase() }).format(amount),
      description: charge.description || charge.statement_descriptor || 'Payment',
      receiptUrl: charge.receipt_url || '',
      paidAt: new Date((charge.created || Date.now() / 1000) * 1000).toISOString(),
      livemode: charge.livemode === true,
    },
  };
});

